> Javascript is awesome (no, it's not!) 

Il sito si apre con una encoded flag: `synt{jnvg_vf_guvf_pelcgb_be_jro}`. Ma nel source code c'è uno script JS che estraiamo:

```javascript
document.getElementById("myForm").addEventListener("submit", function (event) {
  event.preventDefault();
  const inputText = document.getElementById("inputText").value;
  const encoded_flag = "synt{jnvg_vf_guvf_pelcgb_be_jro}";
  check_value(encoded_flag, inputText);
});

function customEncode(inputString, shift) {
  if (typeof inputString !== "string" || typeof shift !== "number") {
    throw new Error("Input must be a string, and shift must be a number");
  }

  let encodedString = "";

  for (let i = 0; i < inputString.length; i++) {
    const char = inputString.charAt(i);
    const charCode = inputString.charCodeAt(i);

    if (/[a-zA-Z]/.test(char)) {
      const isUpperCase = char === char.toUpperCase();
      const baseCharCode = isUpperCase ? "A".charCodeAt(0) : "a".charCodeAt(0);
      const shiftedCharCode =
        ((((charCode - baseCharCode + shift) % 26) + 26) % 26) + baseCharCode;
      encodedString += String.fromCharCode(shiftedCharCode);
    } else {
      encodedString += char;
    }
  }

  return encodedString;
}

function customDecode(encodedString, shift) {
  return customEncode(encodedString, -shift);
}

function check_value(encodedString, plaintext) {
  if (encodedString === customEncode(plaintext, 13)) {
    document.getElementById("success").innerHTML =
      "Winner winner chicken dinner!!!";
  }
}
```

La flag è codificata con **rot13** (uno shift di 13 lettere, comune nelle CTF). Nel JS c'è una funzione *customEncode* che viene usata per la cifratura della flag, ma è presente anche la funzione **customDecode**; chiamare tale funzione da console browser passando come input la flag criptata e lo shift 13 riceviamo la flag finale. Il comando è proprio:

```javascript
customDecode("synt{jnvg_vf_guvf_pelcgb_be_jro}", 13)
```

from Crypto.Cipher import DES, AES, ChaCha20
from Crypto.Util.Padding import pad, unpad

def main():
	print("Scegli algoritmo: DES, AES, ChaCha20")
	algo = input("Algoritmo: ").strip().upper()
	op = input("Operazione (encrypt/decrypt): ").strip().lower()
	key_hex = input("Chiave (hex): ").strip()
	key = bytes.fromhex(key_hex)

	if algo == "DES":
		mode = input("Modalità (CBC): ").strip().upper() or "CBC"
		iv_hex = input("IV (hex, 8 byte): ").strip()
		iv = bytes.fromhex(iv_hex)
		if op == "encrypt":
			pt = input("Plaintext: ").encode()
			padding = input("Padding (x923/pkcs7/none): ").strip().lower() or "x923"
			if padding == "none":
				padded = pt
			else:
				padded = pad(pt, 8, padding)
			cipher = DES.new(key, DES.MODE_CBC, iv=iv)
			ct = cipher.encrypt(padded)
			print("Ciphertext (hex):", ct.hex())
		else:
			ct = bytes.fromhex(input("Ciphertext (hex): ").strip())
			cipher = DES.new(key, DES.MODE_CBC, iv=iv)
			pt = cipher.decrypt(ct)
			try:
				padding = input("Padding (x923/pkcs7/none): ").strip().lower() or "x923"
				if padding == "none":
					print("Plaintext:", pt.decode())
				else:
					print("Plaintext:", unpad(pt, 8, padding).decode())
			except Exception as e:
				print("Plaintext (raw):", pt)

	elif algo == "AES":
		mode = input("Modalità (CFB/CBC): ").strip().upper() or "CFB"
		iv_hex = input("IV (hex, 16 byte, vuoto=auto): ").strip()
		iv = bytes.fromhex(iv_hex) if iv_hex else None
		segment_size = 128
		if mode == "CFB":
			try:
				segment_size = int(input("Segment size (default 128): ") or 128)
			except:
				segment_size = 128
		if op == "encrypt":
			pt = input("Plaintext: ").encode()
			padding = input("Padding (pkcs7/none): ").strip().lower() or "pkcs7"
			if padding == "none":
				padded = pt
			else:
				padded = pad(pt, 16, padding)
			if mode == "CFB":
				cipher = AES.new(key, AES.MODE_CFB, iv=iv, segment_size=segment_size) if iv else AES.new(key, AES.MODE_CFB, segment_size=segment_size)
			else:
				cipher = AES.new(key, AES.MODE_CBC, iv=iv) if iv else AES.new(key, AES.MODE_CBC)
			ct = cipher.encrypt(padded)
			print("Ciphertext (hex):", ct.hex())
			print("IV usato:", cipher.iv.hex())
		else:
			ct = bytes.fromhex(input("Ciphertext (hex): ").strip())
			if mode == "CFB":
				cipher = AES.new(key, AES.MODE_CFB, iv=iv, segment_size=segment_size)
			else:
				cipher = AES.new(key, AES.MODE_CBC, iv=iv)
			pt = cipher.decrypt(ct)
			try:
				padding = input("Padding (pkcs7/none): ").strip().lower() or "pkcs7"
				if padding == "none":
					print("Plaintext:", pt.decode())
				else:
					print("Plaintext:", unpad(pt, 16, padding).decode())
			except Exception as e:
				print("Plaintext (raw):", pt)

	elif algo == "CHACHA20":
		nonce_hex = input("Nonce (hex, 8 byte): ").strip()
		nonce = bytes.fromhex(nonce_hex)
		if op == "encrypt":
			pt = input("Plaintext: ").encode()
			cipher = ChaCha20.new(key=key, nonce=nonce)
			ct = cipher.encrypt(pt)
			print("Ciphertext (hex):", ct.hex())
		else:
			ct = bytes.fromhex(input("Ciphertext (hex): ").strip())
			cipher = ChaCha20.new(key=key, nonce=nonce)
			pt = cipher.decrypt(ct)
			try:
				print("Plaintext:", pt.decode())
			except:
				print("Plaintext (raw):", pt)
	else:
		print("Algoritmo non supportato.")

if __name__ == "__main__":
	main()

from pwn import *
import re

def main():
    HOST = "software-17.challs.olicyber.it"
    PORT = 13001
    r = remote(HOST, PORT)
    r.recvuntil(b"... Invia un qualsiasi carattere per iniziare ...")
    r.sendline(b"LEESGGGGOOO")

    for i in range(101):
        while True:
            try:
                line = r.recvline().decode()
            except EOFError:
                return
            print(line.strip())
            # cerco la stringa che contiene il numero da restituire
            if "packed a" in line:
                match = re.search(r'restituiscimi (0x[0-9a-fA-F]+|\d+) packed a (32|64)-bit', line)
                # se trovo la stringa
                if match:
                    num_str = match.group(1) # prendo il numero
                    bits = int(match.group(2)) # prendo il numero di bit
                    # converto il numero in un intero
                    if num_str.startswith("0x"): 
                        num = int(num_str, 16) # se il numero è esadecimale
                    else:
                        num = int(num_str) # se il numero è decimale
                    # packing
                    if bits == 64:
                        packed = p64(num) # se il numero è a 64 bit
                    else:
                        packed = p32(num) # se il numero è a 32 bit
                    print(f"risposta inviata da noi: {packed.hex()}") # stampa nostra risposta
                    r.send(packed) # invio la risposta
                    break

    try:
        flag = r.recvline().decode().strip() # ricevo la flag
        print(f"flag: {flag}") # stampa la flag
    except EOFError: # per evitare errori se il server chiude la connessione
        pass

if __name__ == "__main__":
    main()

